/**
 * Independently validate version applicability, exact source differences and conservative missing-content semantics.
 * Fixtures use distinct handwritten paragraphs/warnings; real-corpus cases expose reused E-104 and calibration warnings.
 * Symbol index (generated by tools/update-symbol-index.ts):
 * @@SYMBOL_INDEX_START
 * - variable REQUEST: line 23
 * - variable WARNING: line 29
 * - variable SECTION: line 35
 * - function topic: line 44
 * @@SYMBOL_INDEX_END
 */
import { describe, expect, it } from "vitest";
import { PRODUCTS } from "../../src/data/products";
import type { TopicDocument, TopicSection, WarningNotice } from "../../src/lib/contracts";
import {
  compareTopics,
  comparisonRequests,
  comparisonUrl,
  type ComparisonRequest,
} from "../../src/lib/comparison";
import { loadTopics } from "../../tools/load-topics";

const REQUEST: ComparisonRequest = {
  productId: "apex-control-hub",
  from: "1.5",
  to: "2.0",
  slug: "reference-check",
};
const WARNING: WarningNotice = {
  level: "caution",
  condition: "Loop is active",
  consequence: "Readings can be mistaken for process values",
  avoidance: "Use a reviewed maintenance state",
};
const SECTION: TopicSection = {
  id: "checks",
  title: "Reference checks",
  paragraphs: ["Record the reference instrument."],
  steps: ["Isolate the sample loop.", "Verify the known reference."],
  code: "check --fixture",
  warning: WARNING,
};
/** Return a fresh canonical fixture with valid catalog applicability and independent version identities. */
function topic(
  version: "1.5" | "2.0",
  sections: readonly TopicSection[] = [SECTION],
): TopicDocument {
  return {
    id: `apex-${version.replace(".", "-")}-reference`,
    topicSlug: REQUEST.slug,
    productId: REQUEST.productId,
    productName: "Apex Control Hub",
    version,
    lifecycle: version === "2.0" ? "current" : "maintained",
    title: "Reference check",
    summary: "Check reference readings for the selected version.",
    contentType: "task",
    identifiers: ["CHECK-1", "REF-2"],
    synonyms: [],
    updated: "2026-09-01",
    visibility: "public",
    provenance: { sourceId: "reference-fixture", pages: [1], checksum: "a".repeat(64) },
    sections: structuredClone(sections),
  };
}

describe("exact edition comparisons", () => {
  it("keeps unchanged section content and complete provenance separated by version", () => {
    const left = topic("1.5"),
      right = topic("2.0");
    const result = compareTopics([left, right], PRODUCTS, REQUEST);
    expect(result.sections).toMatchObject([
      { id: "checks", status: "unchanged", warningStatus: "unchanged" },
    ]);
    expect(result.before).toBe(left);
    expect(result.after).toBe(right);
    expect(result.beforeUrl).toBe("/docs/apex-control-hub/1.5/reference-check/");
    expect(result.afterUrl).toBe("/docs/apex-control-hub/2.0/reference-check/");
    expect(result).toMatchObject({
      summaryChanged: false,
      identifiersChanged: false,
      sectionOrderChanged: false,
    });
  });
  it.each(["title", "paragraphs", "steps", "code"] as const)(
    "marks a changed %s without blending source text",
    (field) => {
      const updated = {
        ...SECTION,
        [field]:
          field === "paragraphs" || field === "steps"
            ? ["Different authored value"]
            : "Different authored value",
      };
      const result = compareTopics([topic("1.5"), topic("2.0", [updated])], PRODUCTS, REQUEST);
      expect(result.sections[0]?.status).toBe("changed");
      expect(result.sections[0]?.before).toEqual(SECTION);
      expect(result.sections[0]?.after).toEqual(updated);
    },
  );
  it.each(["level", "condition", "consequence", "avoidance"] as const)(
    "detects changed warning %s",
    (field) => {
      const warning = {
        ...WARNING,
        [field]: field === "level" ? "danger" : "Revised warning text",
      };
      const result = compareTopics(
        [topic("1.5"), topic("2.0", [{ ...SECTION, warning }])],
        PRODUCTS,
        REQUEST,
      );
      expect(result.sections[0]).toMatchObject({ status: "changed", warningStatus: "changed" });
    },
  );
  it("exposes removed/added sections and warnings while preserving source order and exact optional content", () => {
    const left = topic("1.5", [
      SECTION,
      { id: "legacy", title: "Legacy notice", paragraphs: ["Old edition only."] },
    ]);
    const right = topic("2.0", [
      { id: "new", title: "New check", paragraphs: ["New edition only."], warning: WARNING },
      { id: "checks", title: SECTION.title, paragraphs: SECTION.paragraphs },
    ]);
    const result = compareTopics([left, right], PRODUCTS, REQUEST);
    expect(result.sections.map((row) => [row.id, row.status, row.warningStatus])).toEqual([
      ["checks", "changed", "absent"],
      ["legacy", "absent", "none"],
      ["new", "added", "added"],
    ]);
    expect(result.sectionOrderChanged).toBe(true);
    expect(result.sections[0]?.before?.warning).toEqual(WARNING);
    expect(result.sections[0]?.after?.warning).toBeUndefined();
  });
  it("recognizes absent optional steps/code/warnings consistently and reports identity/title changes", () => {
    const basic: TopicSection = {
      id: "checks",
      title: "Checks",
      paragraphs: ["Read the reference."],
    };
    const right = {
      ...topic("2.0", [{ ...basic, steps: [] }]),
      title: "Updated reference",
      identifiers: ["REF-2", "CHECK-1"],
    };
    const result = compareTopics([topic("1.5", [basic]), right], PRODUCTS, REQUEST);
    expect(result.sections[0]).toMatchObject({ status: "unchanged", warningStatus: "none" });
    expect(result.summaryChanged).toBe(true);
    expect(result.identifiersChanged).toBe(false);
    expect(
      compareTopics([topic("1.5"), { ...topic("2.0"), identifiers: ["NEW-3"] }], PRODUCTS, REQUEST)
        .identifiersChanged,
    ).toBe(true);
  });
  it.each(["before", "after"])(
    "explicitly retains a missing %s edition without substituting another topic",
    (missing) => {
      const result = compareTopics(
        [topic(missing === "before" ? "2.0" : "1.5"), { ...topic("2.0"), topicSlug: "unrelated" }],
        PRODUCTS,
        REQUEST,
      );
      expect(result[missing as "before" | "after"]).toBeUndefined();
      expect(result.sections[0]?.status).toBe(missing === "before" ? "added" : "absent");
      expect(result.summaryChanged).toBe(false);
    },
  );
  it("does not conflate a same-slug topic from another product", () => {
    const other = { ...topic("2.0"), productId: "northstar-io-gateway" };
    expect(compareTopics([topic("1.5"), other], PRODUCTS, REQUEST).after).toBeUndefined();
  });
});

describe("invalid/ambiguous comparison boundaries", () => {
  it.each([
    { ...REQUEST, productId: "not-a-product" },
    { ...REQUEST, from: "9.9" },
    { ...REQUEST, to: "9.9" },
    { ...REQUEST, to: "1.5" },
  ])("rejects unknown or identical versions %j", (request) => {
    expect(() => compareTopics([topic("1.5")], PRODUCTS, request)).toThrow(
      "distinct known versions",
    );
  });
  it.each(["//external", "../path", "<script>", "x?url=https://evil.test", "a".repeat(129)])(
    "rejects hostile path segment %s",
    (slug) => {
      expect(() => comparisonUrl({ ...REQUEST, slug })).toThrow("path segment");
    },
  );
  it.each(["1/2", "1.5?x", "-1.5", "1234567.0"])("rejects invalid version path %s", (to) => {
    expect(() => comparisonUrl({ ...REQUEST, to })).toThrow("path segment");
  });
  it("fails missing both editions and duplicate stable topic keys rather than picking an arbitrary source", () => {
    expect(() => compareTopics([], PRODUCTS, REQUEST)).toThrow("neither edition");
    for (const version of ["1.5", "2.0"] as const) {
      expect(() => compareTopics([topic(version), topic(version)], PRODUCTS, REQUEST)).toThrow(
        "ambiguous stable topic",
      );
    }
  });
  it("rejects duplicate/excessive section identities and overlarge corpora", () => {
    for (const sections of [
      [SECTION, SECTION],
      Array.from({ length: 129 }, (_, index) => ({ ...SECTION, id: `section-${index}` })),
    ]) {
      expect(() => compareTopics([topic("1.5", sections)], PRODUCTS, REQUEST)).toThrow(
        "section identities",
      );
    }
    const many = Array.from({ length: 1001 }, () => topic("1.5"));
    expect(() => compareTopics(many, PRODUCTS, REQUEST)).toThrow("1000 topics");
    expect(() => comparisonRequests(many, PRODUCTS)).toThrow("1000 topics");
  });
  it("fails the static route budget before a larger catalog can create an unusable chooser", () => {
    const versions = Array.from({ length: 33 }, (_, index) => ({
      version: `${index + 1}.0`,
      lifecycle: "current" as const,
      released: "2026-01-01",
    }));
    const product = {
      id: REQUEST.productId,
      name: "Apex Control Hub",
      description: "Route budget fixture",
      versions,
    };
    const topics = versions.map((version) => ({ ...topic("2.0"), version: version.version }));
    expect(() => comparisonRequests(topics, [product])).toThrow("1000 pages");
  });
  it.each([{ lifecycle: "current" }, { productName: "Wrong product" }])(
    "rejects catalog applicability disagreement %j",
    (override) => {
      const wrong = Object.assign(topic("1.5"), override);
      expect(() => compareTopics([wrong], PRODUCTS, REQUEST)).toThrow("applicability");
    },
  );
});

describe("actual synthetic product editions", () => {
  it("shows that the same E-104 identity changed meaning and warning between known versions", async () => {
    const result = compareTopics(await loadTopics(), PRODUCTS, { ...REQUEST, slug: "error-e-104" });
    expect(result.before?.summary).toContain("Ethernet address");
    expect(result.after?.summary).toContain("trust certificate");
    expect(result).toMatchObject({ summaryChanged: true, identifiersChanged: true });
    expect(result.sections.find((row) => row.id === "meaning")?.warningStatus).toBe("changed");
  });
  it("retains the complete calibration warning when comparing to an older edition without it", async () => {
    const result = compareTopics(await loadTopics(), PRODUCTS, {
      productId: "northstar-io-gateway",
      from: "3.2",
      to: "3.0",
      slug: "analog-input-calibration",
    });
    expect(result.sections[0]).toMatchObject({ warningStatus: "absent", status: "changed" });
    expect(result.before?.sections[0]?.warning?.avoidance).toContain("maintenance state");
  });
  it("marks a retired version's missing counterpart and emits unique reversible, valid canonical paths", async () => {
    const topics = await loadTopics();
    const result = compareTopics(topics, PRODUCTS, { ...REQUEST, to: "1.0", slug: "error-e-104" });
    expect(result.toVersion.lifecycle).toBe("retired");
    expect(result.after).toBeUndefined();
    const requests = comparisonRequests(topics, PRODUCTS);
    const urls = requests.map(comparisonUrl);
    expect(new Set(urls).size).toBe(urls.length);
    expect(requests.length).toBeGreaterThan(20);
    for (const request of requests) {
      expect(() => compareTopics(topics, PRODUCTS, request)).not.toThrow();
      expect(urls).toContain(comparisonUrl({ ...request, from: request.to, to: request.from }));
    }
    expect(comparisonRequests([], PRODUCTS)).toEqual([]);
    expect(comparisonRequests(topics, [])).toEqual([]);
  });
});
